"""Strict dates, month arithmetic and periods."""
import calendar
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    pass


def is_date(value):
    return isinstance(value, date) and not isinstance(value, datetime)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %r: expected text YYYY-MM-DD" % (text,))
    m = _DATE_RE.fullmatch(text)
    if m is None:
        raise DateError("invalid date %r: expected YYYY-MM-DD" % (text,))
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date %r: no such day" % (text,)) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers, got %r and %r" % (year, month))
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise DateError("year/month out of range: %r-%r" % (year, month))
    return calendar.monthrange(year, month)[1]


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    year, month0 = divmod(total, 12)
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s %+d months" % (format_date(d), n))
    month = month0 + 1
    return date(year, month, min(d.day, calendar.monthrange(year, month)[1]))


def _add_days(d, n):
    try:
        return d + timedelta(days=n)
    except OverflowError:
        raise DateError("date out of range: %s %+d days" % (format_date(d), n)) from None


_PERIOD_YEAR = re.compile(r"([0-9]{4})")
_PERIOD_MONTH = re.compile(r"([0-9]{4})-([0-9]{2})")
_PERIOD_QUARTER = re.compile(r"([0-9]{4})-Q([1-4])")
_PERIOD_RANGE = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})")


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got %r and %r" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: end %s is before start %s" % (format_date(self.end), format_date(self.start)))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            m = _PERIOD_YEAR.fullmatch(text)
            if m:
                y = int(m.group(1))
                return cls(date(y, 1, 1), date(y, 12, 31))
            m = _PERIOD_MONTH.fullmatch(text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(date(y, mo, 1), date(y, mo, calendar.monthrange(y, mo)[1]))
            m = _PERIOD_QUARTER.fullmatch(text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                first = 3 * q - 2
                return cls(date(y, first, 1), date(y, first + 2, calendar.monthrange(y, first + 2)[1]))
            m = _PERIOD_RANGE.fullmatch(text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (ValueError, calendar.IllegalMonthError, DateError):
            pass
        raise DateError("invalid period %r: expected 2024, 2024-03, 2024-Q1 or 2024-03-01..2024-03-31" % (text,))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.month == 1 and s.day == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if s.day == 1 and e.year == s.year and e.month == s.month and e.day == calendar.monthrange(s.year, s.month)[1]:
            return "month"
        if (
            s.day == 1
            and s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == calendar.monthrange(e.year, e.month)[1]
        ):
            return "quarter"
        return "range"

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return _whole("year", s.year + 1, 1)
        if kind == "month":
            nxt = add_months(s, 1)
            return _whole("month", nxt.year, nxt.month)
        if kind == "quarter":
            nxt = add_months(s, 3)
            return _whole("quarter", nxt.year, nxt.month)
        start = _add_days(self.end, 1)
        return Period(start, _add_days(start, self.days - 1))


def _whole(kind, year, month):
    if not 1 <= year <= 9999:
        raise DateError("date out of range: year %d" % year)
    if kind == "year":
        return Period(date(year, 1, 1), date(year, 12, 31))
    if kind == "month":
        return Period(date(year, month, 1), date(year, month, calendar.monthrange(year, month)[1]))
    return Period(date(year, month, 1), date(year, month + 2, calendar.monthrange(year, month + 2)[1]))


_STEPS = ("week", "month", "quarter", "year")


def _period_containing(d, step):
    if step == "week":
        monday = _add_days(d, -d.weekday())
        return Period(monday, _add_days(monday, 6))
    if step == "month":
        return _whole("month", d.year, d.month)
    if step == "quarter":
        return _whole("quarter", d.year, 3 * ((d.month - 1) // 3) + 1)
    return _whole("year", d.year, 1)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got %r and %r" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step %r: expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _period_containing(start, step)
    out = [p]
    while p.end < end:
        p = p.next() if step != "week" else Period(_add_days(p.end, 1), _add_days(p.end, 7))
        out.append(p)
    return out
"""The ledger: validated transactions and balances."""
import re

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.dates import format_date, is_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor


class LedgerError(ValidationError):
    pass


_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _line_free(text):
    return isinstance(text, str) and "\n" not in text and "\r" not in text


def _copy(tx):
    return Transaction(tx.date, tx.payee, tx.narration, list(tx.postings), tuple(tx.tags), tx.flag, tx.id)


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation ---------------------------------------------------
    def _build(self, tx, forced_id=None, check_id=True):
        if not isinstance(tx, Transaction):
            raise LedgerError("expected a Transaction, got %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("date must be a datetime.date, got %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("flag must be '*' or '!', got %r" % (tx.flag,))
        if not _line_free(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _line_free(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if isinstance(tx.tags, str):
            raise LedgerError("tags must be a sequence of tag names")
        try:
            tags = list(tx.tags)
        except TypeError:
            raise LedgerError("tags must be a sequence of tag names") from None
        for tag in tags:
            if not isinstance(tag, str) or _TAG.fullmatch(tag) is None:
                raise LedgerError("invalid tag %r" % (tag,))
        try:
            postings = list(tx.postings)
        except TypeError:
            raise LedgerError("postings must be a list") from None
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("expected a Posting, got %r" % (p,))
            if not isinstance(p.account, str):
                raise LedgerError("posting account must be text, got %r" % (p.account,))
            if not _line_free(p.note):
                raise LedgerError("posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be Money or None, got %r" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % p.account)
        for p in postings:
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
        self._check_currencies(postings)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = {c: v for c, v in sums.items() if v != 0}
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = [Posting(gap.account, Money(-off[c], c), gap.note) for c in sorted(off)]
            postings = postings[:i] + filled + postings[i + 1 :]
            self._check_currencies(filled)
        elif off:
            detail = ", ".join("%s %s" % (c, format_minor(off[c], c)) for c in sorted(off))
            raise LedgerError("transaction does not balance: %s" % detail)
        if forced_id is not None:
            tid = forced_id
        elif tx.id is None:
            tid = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("id must be an integer of at least 1, got %r" % (tx.id,))
            if check_id and tx.id in self._txs:
                raise LedgerError("transaction id %d already exists" % tx.id)
            tid = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings, tuple(sorted(set(tags))), tx.flag, tid)

    def _check_currencies(self, postings):
        for p in postings:
            if p.amount is None:
                continue
            held = self.chart.get(p.account).currency
            if held is not None and held != p.amount.currency:
                raise LedgerError("account %s only holds %s, not %s" % (p.account, held, p.amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- writes -------------------------------------------------------
    def add(self, tx):
        stored = self._build(tx)
        self._store(stored)
        return _copy(stored)

    def add_many(self, transactions):
        saved_txs, saved_max = dict(self._txs), self._max_id
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = saved_txs, saved_max
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if isinstance(tx, Transaction) and tx.id is not None and tx.id != id:
            raise LedgerError("replacement id %r does not match %r" % (tx.id, id))
        stored = self._build(tx, forced_id=id)
        self._txs[id] = stored
        return _copy(stored)

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return _copy(self._txs.pop(id))

    # -- reads --------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return _copy(self._txs[id])

    def _sorted(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def transactions(self):
        return [_copy(t) for t in self._sorted()]

    def postings(self):
        for tx in self._sorted():
            copy = _copy(tx)
            for p in copy.postings:
                yield copy, p

    def _selected(self, as_of):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date or None, got %r" % (as_of,))
        for tx in self._txs.values():
            if as_of is None or tx.date <= as_of:
                yield tx

    def balances(self, as_of=None):
        totals = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                cur = totals.setdefault(p.account, {})
                cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
        return _clean(totals)

    def rollup_balances(self, as_of=None):
        totals = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                path = p.account
                while True:
                    cur = totals.setdefault(path, {})
                    cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
                    if ":" not in path:
                        break
                    path = path.rsplit(":", 1)[0]
        return _clean(totals)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        prefix = account + ":"
        sums = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                if p.account == account or (rollup and p.account.startswith(prefix)):
                    c = p.amount.currency
                    sums[c] = sums.get(c, 0) + p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}


def _clean(totals):
    out = {}
    for account, cur in totals.items():
        kept = {c: v for c, v in cur.items() if v != 0}
        if kept:
            out[account] = kept
    return out
"""Error hierarchy: every user-caused failure derives from TallybookError."""


class TallybookError(Exception):
    code = "error"

    def __init__(self, message="", **extra):
        super().__init__(message)
        self.message = message
        self.detail = {}
        for key, value in extra.items():
            setattr(self, key, value)

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"

