"""Currency table and exchange rates."""
import re
from dataclasses import dataclass
from fractions import Fraction

from tallybook.dates import is_date
from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    pass


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


CURRENCIES = {
    c.code: c
    for c in (
        Currency("USD", 2, "US Dollar", "$"),
        Currency("EUR", 2, "Euro", "€"),
        Currency("GBP", 2, "British Pound", "£"),
        Currency("JPY", 0, "Japanese Yen", "¥"),
        Currency("CHF", 2, "Swiss Franc", "CHF"),
        Currency("CAD", 2, "Canadian Dollar", "CA$"),
        Currency("AUD", 2, "Australian Dollar", "A$"),
        Currency("KWD", 3, "Kuwaiti Dinar", "KD"),
        Currency("SEK", 2, "Swedish Krona", "kr"),
        Currency("INR", 2, "Indian Rupee", "₹"),
        Currency("NZD", 2, "New Zealand Dollar", "NZ$"),
        Currency("NOK", 2, "Norwegian Krone", "kr"),
        Currency("KRW", 0, "South Korean Won", "₩"),
        Currency("BHD", 3, "Bahraini Dinar", "BD"),
        Currency("CNY", 2, "Chinese Yuan", "CN¥"),
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    )
}


def currency(code):
    if not isinstance(code, str) or code not in CURRENCIES:
        raise CurrencyError("unknown currency %r" % (code,))
    return CURRENCIES[code]


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def _check_date(on):
    if not is_date(on):
        raise CurrencyError("date must be a datetime.date, got %r" % (on,))


class RateTable:
    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: Fraction}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        if not isinstance(rate_text, str) or _RATE_RE.fullmatch(rate_text) is None:
            raise CurrencyError("invalid rate %r: expected digits with up to 8 decimals" % (rate_text,))
        rate = Fraction(rate_text)
        if rate <= 0:
            raise CurrencyError("invalid rate %r: must be positive" % (rate_text,))
        _check_date(on)
        self._rates.setdefault((src, dst), {})[on] = rate

    def _lookup(self, src, dst, on):
        best = None
        for d, r in self._rates.get((src, dst), {}).items():
            if d <= on and (best is None or d > best[0]):
                best = (d, r)
        return None if best is None else best[1]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._lookup(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._lookup(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, on.isoformat()))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("can only convert Money, got %r" % (money,))
        dst_cur = currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        rate = self.rate(money.currency, dst, on)
        value = Fraction(money.minor) * rate * Fraction(10) ** (dst_cur.exponent - money.exponent)
        return Money(round_div(value.numerator, value.denominator), dst)

    def entries(self):
        out = []
        for (src, dst), by_date in self._rates.items():
            for d, r in by_date.items():
                out.append((src, dst, d, r))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        by_date = self._rates.get((src, dst))
        if not by_date or on not in by_date:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, on.isoformat()))
        del by_date[on]
        if not by_date:
            del self._rates[(src, dst)]
"""Plain data records: Account, Posting, Transaction."""
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from tallybook.money import Money


@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Optional[date] = None
    closed: Optional[date] = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: Optional[Money] = None
    note: str = ""


@dataclass
class Transaction:
    date: date
    payee: str
    narration: str = ""
    postings: List[Posting] = field(default_factory=list)
    tags: Tuple[str, ...] = ()
    flag: str = "*"
    id: Optional[int] = None
"""Chart of accounts."""
import re

from tallybook.currency import CURRENCIES
from tallybook.dates import format_date, is_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    pass


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEGMENT.fullmatch(p) is not None for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,))


def parent_path(path):
    _need_path(path)
    return path.rsplit(":", 1)[0] if ":" in path else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _sort_key(path):
    return tuple(path.split(":"))


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and _SEGMENT.fullmatch(p) is None:
            raise ChartError("invalid account pattern %r" % (pattern,))
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern segments, segs: list of path segments; exact match.
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for take in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[take:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def _pattern_matches(parts, path):
    segs = path.split(":")
    if all(p not in ("*", "**") for p in parts):
        return segs[: len(parts)] == parts
    return _match_segments(parts, segs)


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    return _pattern_matches(parts, path)


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        root_type = account_type(path)
        if type is not None and (not isinstance(type, str) or type not in TYPES or type != root_type):
            raise ChartError("account type %r does not fit %s" % (type, path))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text, got %r" % (note,))
        if path in self._explicit:
            err = ChartError("account %s already exists" % path)
            err.code = "conflict"
            raise err
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            account = existing
        else:
            account = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = account
        self._explicit.add(path)
        parent = parent_path(path)
        while parent is not None:
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, root_type)
            parent = parent_path(parent)
        return account

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def is_explicit(self, path):
        return path in self._explicit

    def children(self, path):
        self.get(path)
        depth = path.count(":") + 1
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix) and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        account = self.get(path)
        if not is_date(on):
            raise ChartError("date must be a date, got %r" % (on,))
        return (account.opened is None or account.opened <= on) and (account.closed is None or on <= account.closed)

    def close(self, path, on):
        account = self.get(path)
        if not is_date(on):
            raise ChartError("close date must be a date, got %r" % (on,))
        if account.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if account.opened is not None and on < account.opened:
            raise ChartError("cannot close %s on %s: before it opened on %s" % (path, format_date(on), format_date(account.opened)))
        account.closed = on
        return account

    def matches(self, pattern):
        parts = _check_pattern(pattern)
        return [a for a in self.accounts() if _pattern_matches(parts, a.path)]
"""Money: integer minor units plus a currency code. No floats anywhere."""
import re

from tallybook.currency import CurrencyError, currency as _currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    pass


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """Quotient n/d rounded half away from zero (d > 0)."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, currency):
    exponent = _currency(currency).exponent
    if not _is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if exponent == 0:
        return sign + digits
    digits = digits.rjust(exponent + 1, "0")
    return "%s%s.%s" % (sign, digits[:-exponent], digits[-exponent:])


def parse_amount(text, currency):
    exponent = _currency(currency).exponent
    if not isinstance(text, str):
        raise MoneyError("amount must be text, got %r" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if m is None:
        raise MoneyError("invalid amount %r" % (text,))
    sign, whole, frac = m.groups()
    frac = frac or ""
    if m.group(3) is not None and exponent == 0:
        raise MoneyError("invalid amount %r: %s has no decimals" % (text, currency))
    if len(frac) > exponent:
        raise MoneyError("invalid amount %r: %s has only %d decimals" % (text, currency, exponent))
    minor = int(whole + frac.ljust(exponent, "0"))
    return -minor if sign == "-" else minor


