"""Budgets: allowances per calendar period and how spending compares."""
import re
from dataclasses import dataclass
from decimal import Decimal
from fractions import Fraction

from tallybook.dates import Period, is_date, last_day
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div


class BudgetError(ValidationError):
    pass


_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")
_KINDS = ("month", "quarter", "year")
