"""Recurring transactions: schedules, series of dates and dated copies of a template."""
import re
from dataclasses import dataclass
from datetime import date, timedelta
from typing import Optional

from tallybook.dates import DateError, add_months, is_date, last_day, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Transaction


class RecurringError(ValidationError):
    pass


_SHAPES = (
    "daily, weekly on mon..sun, monthly on 1..31, monthly on last, yearly on MM-DD, "
    "every N days|weeks|months|years from YYYY-MM-DD"
)
_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week", "month": "month", "months": "month",
          "year": "year", "years": "year"}
_UNIT_DAYS = {"day": 1, "week": 7}
_UNIT_MONTHS = {"month": 1, "year": 12}
_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_INT = re.compile(r"[0-9]+")
_MMDD = re.compile(r"([0-9]{2})-([0-9]{2})")
_MAX_ORD = date.max.toordinal()


def _bad(text):
    return RecurringError("invalid schedule %r: expected one of: %s" % (text, _SHAPES))


@dataclass(frozen=True)
class Schedule:
    kind: str  # daily weekly monthly yearly every
    weekday: Optional[int] = None
    day: object = None  # int, or "last" for monthly
    month: Optional[int] = None
    n: Optional[int] = None
    unit: Optional[str] = None  # singular
    anchor: Optional[date] = None

    def __str__(self):
        if self.kind == "daily":
            return "daily"
        if self.kind == "weekly":
            return "weekly on " + _WEEKDAYS[self.weekday]
        if self.kind == "monthly":
            return "monthly on %s" % (self.day,)
        if self.kind == "yearly":
            return "yearly on %02d-%02d" % (self.month, self.day)
        unit = self.unit if self.n == 1 else self.unit + "s"
        return "every %d %s from %s" % (self.n, unit, self.anchor.isoformat())

    # -- dates by rank: the schedule's own dates, 1-based, from year 1 on --------------
    def _count_upto(self, d):
        """How many of the schedule's dates are on or before d."""
        o = d.toordinal()
        kind = self.kind
        if kind == "daily":
            return o
        if kind == "weekly":
            first = 1 + self.weekday
            return 0 if o < first else (o - first) // 7 + 1
        if kind == "monthly":
            idx = d.year * 12 + d.month - 1 - 12
            return idx + (1 if self._day_in_month(d.year, d.month) <= d.day else 0)
        if kind == "yearly":
            return d.year - 1 + (1 if self._day_in_year(d.year) <= (d.month, d.day) else 0)
        if self.unit in _UNIT_DAYS:
            step = self.n * _UNIT_DAYS[self.unit]
            first = self.anchor.toordinal()
            return 0 if o < first else (o - first) // step + 1
        step = self.n * _UNIT_MONTHS[self.unit]
        diff = (d.year * 12 + d.month) - (self.anchor.year * 12 + self.anchor.month)
        if diff < 0:
            return 0
        j = diff // step
        if diff % step == 0 and add_months(self.anchor, j * step) > d:
            return j
        return j + 1

    def _nth(self, k):
        """The k-th (1-based) date of the schedule, or None past the end of the calendar."""
        kind = self.kind
        if kind == "daily":
            o = k
        elif kind == "weekly":
            o = 1 + self.weekday + 7 * (k - 1)
        elif kind == "monthly":
            year, month0 = divmod(12 + k - 1, 12)
            if year > 9999:
                return None
            return date(year, month0 + 1, self._day_in_month(year, month0 + 1))
        elif kind == "yearly":
            if k > 9999:
                return None
            month, day = self._day_in_year(k)
            return date(k, month, day)
        elif self.unit in _UNIT_DAYS:
            o = self.anchor.toordinal() + self.n * _UNIT_DAYS[self.unit] * (k - 1)
        else:
            try:
                return add_months(self.anchor, self.n * _UNIT_MONTHS[self.unit] * (k - 1))
            except DateError:
                return None
        if o > _MAX_ORD:
            return None
        return date.fromordinal(o)

    def _day_in_month(self, year, month):
        ld = last_day(year, month)
        return ld if self.day == "last" else min(self.day, ld)

    def _day_in_year(self, year):
        if self.month == 2 and self.day == 29 and last_day(year, 2) != 29:
            return (2, 28)
        return (self.month, self.day)

    def between(self, start, end):
        if not is_date(start) or not is_date(end):
            raise RecurringError("between needs two dates, got %r and %r" % (start, end))
        return _dates(self, start, end, 0, None)


def _before(d):
    return None if d == date.min else d - timedelta(days=1)


def _rank_before(schedule, d):
    prev = _before(d)
    return 0 if prev is None else schedule._count_upto(prev)


def _dates(schedule, lo, hi, first_rank, last_rank):
    """Schedule dates in lo..hi whose rank is above first_rank and at most last_rank (None: no limit)."""
    if hi < lo:
        return []
    a = max(first_rank, _rank_before(schedule, lo))
    b = schedule._count_upto(hi)
    if last_rank is not None:
        b = min(b, last_rank)
    out = []
    for k in range(a + 1, b + 1):
        out.append(schedule._nth(k))
    return out


def parse_schedule(text):
    if not isinstance(text, str):
        raise RecurringError("invalid schedule %r: expected text; allowed: %s" % (text, _SHAPES))
    words = text.lower().split()
    try:
        if words == ["daily"]:
            return Schedule("daily")
        if len(words) == 3 and words[:2] == ["weekly", "on"] and words[2] in _WEEKDAYS:
            return Schedule("weekly", weekday=_WEEKDAYS.index(words[2]))
        if len(words) == 3 and words[:2] == ["monthly", "on"]:
            if words[2] == "last":
                return Schedule("monthly", day="last")
            if _INT.fullmatch(words[2]) and 1 <= int(words[2]) <= 31:
