            m = _MMDD.fullmatch(words[2])
            if m:
                month, day = int(m.group(1)), int(m.group(2))
                if 1 <= month <= 12 and 1 <= day <= last_day(2000, month):
                    return Schedule("yearly", month=month, day=day)
        if len(words) == 5 and words[0] == "every" and words[3] == "from":
            if _INT.fullmatch(words[1]) and int(words[1]) >= 1 and words[2] in _UNITS:
                return Schedule("every", n=int(words[1]), unit=_UNITS[words[2]], anchor=parse_date(words[4]))
    except DateError:
        pass
    raise _bad(text)


class Recurring:
    __slots__ = ("name", "schedule", "template", "start", "end", "count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or _NAME.fullmatch(name) is None or not name.isascii():
            raise RecurringError("invalid name %r: use ASCII letters, digits, - and _, not starting with - or _" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("schedule must be a Schedule or text, got %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, got %r" % (template,))
        if not is_date(start):
            raise RecurringError("start must be a datetime.date, got %r" % (start,))
        if end is not None:
            if not is_date(end):
                raise RecurringError("end must be a datetime.date or None, got %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (end.isoformat(), start.isoformat()))
        if count is not None and (not isinstance(count, int) or isinstance(count, bool) or count < 1):
            raise RecurringError("count must be an integer of at least 1 or None, got %r" % (count,))
        for key, value in (("name", name), ("schedule", schedule), ("template", template), ("start", start),
                           ("end", end), ("count", count)):
            object.__setattr__(self, key, value)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return False
        return all(getattr(self, k) == getattr(other, k) for k in self.__slots__)

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, %r, start=%s, end=%s, count=%r)" % (
            self.name, str(self.schedule), self.start.isoformat(), self.end, self.count)


def _need_window(start, end):
    if not is_date(start) or not is_date(end):
        raise RecurringError("window needs two dates, got %r and %r" % (start, end))


def _need_rec(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("expected a Recurring, got %r" % (rec,))


def occurrences(rec, start, end):
    _need_rec(rec)
    _need_window(start, end)
    sched = rec.schedule
    lo = max(start, rec.start)
    hi = end if rec.end is None else min(end, rec.end)
    base = _rank_before(sched, rec.start)
    last = None if rec.count is None else base + rec.count
    return _dates(sched, lo, hi, base, last)


def next_occurrence(rec, after):
    _need_rec(rec)
    if not is_date(after):
        raise RecurringError("after must be a datetime.date, got %r" % (after,))
    sched = rec.schedule
    base = _rank_before(sched, rec.start)
    k = max(base, sched._count_upto(after)) + 1
    if rec.count is not None and k > base + rec.count:
        return None
    d = sched._nth(k)
    if d is None or (rec.end is not None and d > rec.end):
        return None
    return d


def instantiate(rec, on):
    _need_rec(rec)
    if not is_date(on):
        raise RecurringError("date must be a datetime.date, got %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    _need_window(start, end)
    recs = list(recs)
    found = []
    for index, rec in enumerate(recs):
        _need_rec(rec)
        for d in occurrences(rec, start, end):
            found.append((d, rec.name, index))
    found.sort()
    return [instantiate(recs[i], d) for d, _, i in found]


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        return "%dth" % n
    return "%d%s" % (n, {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th"))


def describe(schedule):
    if isinstance(schedule, str):
        schedule = parse_schedule(schedule)
    if not isinstance(schedule, Schedule):
        raise RecurringError("expected a Schedule, got %r" % (schedule,))
    kind = schedule.kind
    if kind == "daily":
        return "every day"
    if kind == "weekly":
        return "every " + _WEEKDAY_NAMES[schedule.weekday]
    if kind == "monthly":
        if schedule.day == "last":
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(schedule.day)
    if kind == "yearly":
        return "every year on %d %s" % (schedule.day, _MONTH_NAMES[schedule.month - 1])
    if schedule.n == 1:
        step = "every %s" % schedule.unit
    else:
        step = "every %d %ss" % (schedule.n, schedule.unit)
    return "%s from %s" % (step, schedule.anchor.isoformat())

