"""Reports: plain dicts built from a ledger, drawn as text or CSV."""
from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import DateError, Period, is_date, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div


class ReportError(ValidationError):
    pass


_REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
_STEPS = ("week", "month", "quarter", "year")


# -- helpers -------------------------------------------------------------------------
def _need_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("expected a Ledger, got %r" % (ledger,))


def _need_period(period):
    if not isinstance(period, Period):
        raise ReportError("expected a Period, got %r" % (period,))


def _need_as_of(as_of):
    if as_of is not None and not is_date(as_of):
        raise ReportError("as_of must be a date or None, got %r" % (as_of,))


def _day(d):
    return None if d is None else d.isoformat()


def _kind(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, cur):
    return money_to_dict(Money(minor, cur))


def _sorted_money(sums, keep_zero=False):
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _percent_text(minor, total):
    if total == 0:
        return "0.0"
    if total < 0:
        minor, total = -minor, -total
    tenths = round_div(minor * 1000, total)
    sign = "-" if tenths < 0 else ""
    return "%s%d.%d" % (sign, abs(tenths) // 10, abs(tenths) % 10)


def _by_account(postings, keep):
    """{(account, currency): minor} over (date, posting) pairs satisfying keep."""
    sums = {}
    for _, p in postings:
        if keep(p):
            key = (p.account, p.amount.currency)
            sums[key] = sums.get(key, 0) + p.amount.minor
    return sums


def _check_convert(convert_to):
    if convert_to is not None:
        _currency(convert_to)


# -- trial balance -------------------------------------------------------------------
def trial_balance(ledger, as_of=None):
    _need_ledger(ledger)
    _need_as_of(as_of)
    entries = []
    for account, by_cur in ledger.balances(as_of).items():
        for cur, minor in by_cur.items():
            if minor != 0:
                entries.append((account, cur, minor))
    entries.sort(key=lambda e: (e[0], e[1]))
    accounts = []
    debits, credits = {}, {}
    for account, cur, minor in entries:
        debits.setdefault(cur, 0)
        credits.setdefault(cur, 0)
        if minor > 0:
            debits[cur] += minor
            accounts.append({"account": account, "type": _kind(account), "debit": _m(minor, cur), "credit": None})
        else:
            credits[cur] += -minor
            accounts.append({"account": account, "type": _kind(account), "debit": None, "credit": _m(-minor, cur)})
    totals = [
        {"currency": c, "debit": _m(debits[c], c), "credit": _m(credits[c], c), "balanced": debits[c] == credits[c]}
        for c in sorted(debits)
    ]
    return {"report": "trial_balance", "as_of": _day(as_of), "accounts": accounts, "totals": totals}


# -- balance sheet -------------------------------------------------------------------
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _need_ledger(ledger)
    _need_as_of(as_of)
    _check_convert(convert_to)
    if convert_to is not None and as_of is None:
        raise ReportError("convert_to needs an as_of date to pick the exchange rates")
    balances = ledger.balances(as_of)
    lines = {"asset": [], "liability": [], "equity": []}
    earned = {}
    for account in sorted(balances):
        kind = _kind(account)
        for cur, minor in sorted(balances[account].items()):
            if minor == 0:
                continue
            if kind == "asset":
                lines["asset"].append((account, cur, minor))
            elif kind in ("liability", "equity"):
                lines[kind].append((account, cur, -minor))
            elif kind in ("income", "expense"):
                earned[cur] = earned.get(cur, 0) - minor
    retained = [(c, v) for c, v in sorted(earned.items()) if v != 0]

    def section(entries, extra=()):
        if convert_to is None:
            sums = {}
            out = []
            for account, cur, minor in entries:
                out.append({"account": account, "balance": _m(minor, cur)})
                sums[cur] = sums.get(cur, 0) + minor
            for cur, minor in extra:
                sums[cur] = sums.get(cur, 0) + minor
            return out, _sorted_money(sums, True), sums
        total = 0
        out = []
        for account, cur, minor in entries:
            original = Money(minor, cur)
            converted = ledger.rates.convert(original, convert_to, as_of)
            out.append({"account": account, "balance": money_to_dict(converted), "original": money_to_dict(original)})
            total += converted.minor
        for cur, minor in extra:
            total += ledger.rates.convert(Money(minor, cur), convert_to, as_of).minor
        return out, [_m(total, convert_to)], {convert_to: total}

    a_lines, a_total, a_sums = section(lines["asset"])
    l_lines, l_total, l_sums = section(lines["liability"])
    e_lines, e_total, e_sums = section(lines["equity"], retained)
    if convert_to is None:
        re_list = [_m(v, c) for c, v in retained]
    else:
        re_list = []
        if retained:
            total = sum(ledger.rates.convert(Money(v, c), convert_to, as_of).minor for c, v in retained)
            re_list = [_m(total, convert_to)]
    if convert_to is not None:
        for sums in (a_sums, l_sums, e_sums):
            sums.setdefault(convert_to, 0)
    currencies = set(a_sums) | set(l_sums) | set(e_sums)
    balanced = all(a_sums.get(c, 0) == l_sums.get(c, 0) + e_sums.get(c, 0) for c in currencies)
    if convert_to is not None:
        for sec_total, sums in ((a_total, a_sums), (l_total, l_sums), (e_total, e_sums)):
            pass
    return {
        "report": "balance_sheet",
        "as_of": _day(as_of),
        "currency": convert_to,
        "assets": {"accounts": a_lines, "total": a_total},
        "liabilities": {"accounts": l_lines, "total": l_total},
        "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": e_total},
        "balanced": balanced,
    }


# -- income statement ----------------------------------------------------------------
def income_statement(ledger, period, convert_to=None):
    _need_ledger(ledger)
    _need_period(period)
    _check_convert(convert_to)
    postings = [(tx, p) for tx, p in ledger.postings() if period.start <= tx.date <= period.end]
    incomes = _by_account(postings, lambda p: _kind(p.account) == "income")
    expenses = _by_account(postings, lambda p: _kind(p.account) == "expense")
    income = [(a, c, -v) for (a, c), v in sorted(incomes.items()) if v != 0]
    expense = [(a, c, v) for (a, c), v in sorted(expenses.items()) if v != 0]

    def section(entries):
        rows = []
        for account, cur, minor in entries:
            if convert_to is None:
                rows.append({"account": account, "money": Money(minor, cur), "original": None})
            else:
                original = Money(minor, cur)
                rows.append(
                    {"account": account, "money": ledger.rates.convert(original, convert_to, period.end), "original": original}
                )
        totals = {}
        for row in rows:
            cur = row["money"].currency
            totals[cur] = totals.get(cur, 0) + row["money"].minor
        if convert_to is not None:
            totals = {convert_to: totals.get(convert_to, 0)}
        out = []
        for row in rows:
            m = row["money"]
            line = {"account": row["account"], "amount": money_to_dict(m), "percent": _percent_text(m.minor, totals[m.currency])}
            if row["original"] is not None:
                line["original"] = money_to_dict(row["original"])
            out.append(line)
        return out, totals

    i_lines, i_totals = section(income)
    e_lines, e_totals = section(expense)
    net = {c: i_totals.get(c, 0) - e_totals.get(c, 0) for c in set(i_totals) | set(e_totals)}
    return {
        "report": "income_statement",
        "start": period.start.isoformat(),
        "end": period.end.isoformat(),
        "currency": convert_to,
        "income": {"accounts": i_lines, "total": _sorted_money(i_totals, True)},
        "expenses": {"accounts": e_lines, "total": _sorted_money(e_totals, True)},
        "net": _sorted_money(net, True),
    }


# -- cash flow -----------------------------------------------------------------------
def cashflow(ledger, period):
    _need_ledger(ledger)
    _need_period(period)
    opening, closing = {}, {}
    moves = {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        in_period = tx.date >= period.start
        asset_sum = {}
        for p in tx.postings:
            if _kind(p.account) == "asset":
                cur = p.amount.currency
                closing[cur] = closing.get(cur, 0) + p.amount.minor
                if not in_period:
                    opening[cur] = opening.get(cur, 0) + p.amount.minor
                asset_sum[cur] = asset_sum.get(cur, 0) + p.amount.minor
        if not in_period:
            continue
        for p in tx.postings:
            cur = p.amount.currency
            if _kind(p.account) != "asset" and asset_sum.get(cur, 0) != 0:
                key = (p.account, cur)
                moves[key] = moves.get(key, 0) - p.amount.minor
    for cur in closing:
        opening.setdefault(cur, 0)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for (account, cur), v in sorted(moves.items()):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        elif v < 0:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) + -v
    net = {c: total_in[c] - total_out[c] for c in closing}
    return {
        "report": "cashflow",
        "start": period.start.isoformat(),
        "end": period.end.isoformat(),
        "opening": _sorted_money(opening, True),
        "inflows": inflows,
        "outflows": outflows,
        "total_in": _sorted_money(total_in, True),
        "total_out": _sorted_money(total_out, True),
        "net": _sorted_money(net, True),
        "closing": _sorted_money(closing, True),
    }


# -- register ------------------------------------------------------------------------
def register(ledger, account, period=None, rollup=False):
    _need_ledger(ledger)
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))
    if period is not None:
        _need_period(period)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be True or False, got %r" % (rollup,))
    prefix = account + ":"
    opening, running, seen = {}, {}, set()
    rows = []
    for tx, p in ledger.postings():
        if p.account != account and not (rollup and p.account.startswith(prefix)):
            continue
        if period is not None and tx.date > period.end:
            continue
        cur = p.amount.currency
        seen.add(cur)
        if period is not None and tx.date < period.start:
            opening[cur] = opening.get(cur, 0) + p.amount.minor
            running[cur] = opening[cur]
            continue
        running[cur] = running.get(cur, 0) + p.amount.minor
        rows.append(
            {
                "date": tx.date.isoformat(),
                "id": tx.id,
                "payee": tx.payee,
                "narration": tx.narration,
                "account": p.account,
                "amount": money_to_dict(p.amount),
                "balance": _m(running[cur], cur),
            }
        )
    for cur in seen:
        opening.setdefault(cur, 0)
        running.setdefault(cur, 0)
    return {
        "report": "register",
        "account": account,
        "rollup": rollup,
        "start": None if period is None else period.start.isoformat(),
        "end": None if period is None else period.end.isoformat(),
        "opening": _sorted_money(opening if period is not None else {c: 0 for c in seen}, True),
        "rows": rows,
        "closing": _sorted_money(running, True),
    }


# -- net worth -----------------------------------------------------------------------
def net_worth(ledger, period, step="month"):
    _need_ledger(ledger)
    _need_period(period)
    if not isinstance(step, str) or step not in _STEPS:
        raise ReportError("invalid step %r: expected week, month, quarter or year" % (step,))
    try:
        spans = periods(period.start, period.end, step)
    except DateError as exc:
        raise ReportError(exc.message) from None
    events = []
    for tx, p in ledger.postings():
        kind = _kind(p.account)
        if kind in ("asset", "liability"):
            events.append((tx.date, kind, p.amount))
    assets, liabilities, seen = {}, {}, set()
    points = []
    i = 0
    for span in spans:
        while i < len(events) and events[i][0] <= span.end:
            _, kind, amount = events[i]
            target = assets if kind == "asset" else liabilities
            target[amount.currency] = target.get(amount.currency, 0) + amount.minor
            seen.add(amount.currency)
            i += 1
        a = {c: assets.get(c, 0) for c in seen}
        li = {c: -liabilities.get(c, 0) for c in seen}
        net = {c: a[c] - li[c] for c in seen}
        points.append(
            {
                "date": span.end.isoformat(),
                "assets": _sorted_money(a, True),
                "liabilities": _sorted_money(li, True),
                "net": _sorted_money(net, True),
            }
        )
    return {
        "report": "net_worth",
        "start": period.start.isoformat(),
        "end": period.end.isoformat(),
        "step": step,
        "points": points,
    }


# -- text ----------------------------------------------------------------------------
def _txt(money):
    return "%s %s" % (money["amount"], money["currency"])


def _blocks(blocks, width):
    rows = []
    for block in blocks:
        if not block:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(block)
    return rows


def _table_text(title, headers, rows, align):
    return "%s\n\n%s" % (title, render_table(headers, rows, align))


def _text_trial_balance(r):
    title = "Trial balance" if r["as_of"] is None else "Trial balance as of %s" % r["as_of"]
    rows = [
        [a["account"], a["type"], "" if a["debit"] is None else _txt(a["debit"]), "" if a["credit"] is None else _txt(a["credit"])]
        for a in r["accounts"]
    ]
    rows.extend(["Total", "", _txt(t["debit"]), _txt(t["credit"])] for t in r["totals"])
    return _table_text(title, ["Account", "Type", "Debit", "Credit"], rows, "llrr")


def _text_balance_sheet(r):
    title = "Balance sheet" if r["as_of"] is None else "Balance sheet as of %s" % r["as_of"]
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for key, heading, total in (("assets", "Assets", "Total assets"), ("liabilities", "Liabilities", "Total liabilities"),
                                ("equity", "Equity", "Total equity")):
        sec = r[key]
        block = [[heading, ""]]
        block.extend(["  " + a["account"], _txt(a["balance"])] for a in sec["accounts"])
        if key == "equity":
            block.extend(["  Retained earnings", _txt(m)] for m in sec["retained_earnings"])
        block.extend([total, _txt(m)] for m in sec["total"])
        blocks.append(block)
    return _table_text(title, ["Account", "Balance"], _blocks(blocks, 2), "lr")


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for key, heading, total in (("income", "Income", "Total income"), ("expenses", "Expenses", "Total expenses")):
        sec = r[key]
        block = [[heading, "", ""]]
        block.extend(["  " + a["account"], _txt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"])
        block.extend([total, _txt(m), ""] for m in sec["total"])
        blocks.append(block)
    blocks.append([["Net income", _txt(m), ""] for m in r["net"]])
    return _table_text(title, ["Account", "Amount", "Percent"], _blocks(blocks, 3), "lrr")


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])
    blocks = [[["Opening balance", _txt(m)] for m in r["opening"]]]
    for key, heading, total_key, total in (("inflows", "Money in", "total_in", "Total money in"),
                                           ("outflows", "Money out", "total_out", "Total money out")):
        block = [[heading, ""]]
        block.extend(["  " + a["account"], _txt(a["amount"])] for a in r[key])
        block.extend([total, _txt(m)] for m in r[total_key])
        blocks.append(block)
    last = [["Net change", _txt(m)] for m in r["net"]]
    last.extend(["Closing balance", _txt(m)] for m in r["closing"])
    blocks.append(last)
    return _table_text(title, ["Account", "Amount"], _blocks(blocks, 2), "lr")


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for pt in r["points"]:
        if not pt["assets"]:
            rows.append([pt["date"], "", "", ""])
        for a, li, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
            rows.append([pt["date"], _txt(a), _txt(li), _txt(n)])
    return _table_text(title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _txt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else row["id"], row["payee"], row["account"],
                     _txt(row["amount"]), _txt(row["balance"])])
    rows.extend(["", "", "Closing balance", "", "", _txt(m)] for m in r["closing"])
    return _table_text(title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")


_TEXT = {
    "trial_balance": _text_trial_balance,
    "balance_sheet": _text_balance_sheet,
    "income_statement": _text_income_statement,
    "cashflow": _text_cashflow,
    "net_worth": _text_net_worth,
    "register": _text_register,
}


def _need_report(report):
    if not isinstance(report, dict) or report.get("report") not in _REPORTS:
        raise ReportError("not a report: expected a dict made by one of the report functions")


def render_text(report):
    _need_report(report)
    try:
        return _TEXT[report["report"]](report)
    except (KeyError, TypeError, IndexError, AttributeError) as exc:
        raise ReportError("malformed %s report: %r" % (report["report"], exc)) from None


# -- csv -----------------------------------------------------------------------------
def _split(money):
    return money["currency"], money["amount"]


def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        side = a["debit"] if a["debit"] is not None else a["credit"]
        rows.append([a["account"], a["type"], side["currency"],
                     "" if a["debit"] is None else a["debit"]["amount"],
                     "" if a["credit"] is None else a["credit"]["amount"]])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = []
    for m in r["opening"]:
        rows.append(["opening", "", m["currency"], m["amount"]])
    for a in r["inflows"]:
        rows.append(["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]])
    for a in r["outflows"]:
        rows.append(["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]])
    for m in r["closing"]:
        rows.append(["closing", "", m["currency"], m["amount"]])
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = []
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else row["id"], row["payee"], row["narration"], row["account"],
                     row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]])
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for pt in r["points"]:
        for a, li, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
            rows.append([pt["date"], a["currency"], a["amount"], li["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {
    "trial_balance": _csv_trial_balance,
    "balance_sheet": _csv_balance_sheet,
    "income_statement": _csv_income_statement,
    "cashflow": _csv_cashflow,
    "register": _csv_register,
    "net_worth": _csv_net_worth,
}


def report_to_csv(report):
    _need_report(report)
    try:
        headers, rows = _CSV[report["report"]](report)
    except (KeyError, TypeError, IndexError, AttributeError) as exc:
        raise ReportError("malformed %s report: %r" % (report["report"], exc)) from None
    return to_csv(headers, rows)
